import{_ as n,D as e,c as l,I as a,U as i,o as r,a3 as s}from"./chunks/framework.yHs91S0E.js";const k=JSON.parse('{"title":"Announcement: Nix Workshop in Edinburgh!","description":"","frontmatter":{"title":"Announcement: Nix Workshop in Edinburgh!","author":"Noon van der Silk","date":"2026-08-06T00:00:00.000Z","next":false},"headers":[],"relativePath":"articles/nix-workshop-2026.md","filePath":"articles/nix-workshop-2026.md"}'),h={name:"articles/nix-workshop-2026.md"},c=i('<p><img src="'+s+'" alt="Nix Workshop Edinburgh"></p><p>I&#39;m very excited to announce our first Nix workshop!</p><h3 id="wait-what-is-nix-again" tabindex="-1">Wait, what is Nix again? <a class="header-anchor" href="#wait-what-is-nix-again" aria-label="Permalink to &quot;Wait, what is Nix again?&quot;">​</a></h3><p><a href="https://nixos.org/" target="_blank" rel="noreferrer">Nix</a> is a whole-system package manager and development tool. It can bring in <em>all</em> dependencies, so you never need to again worry about &quot;Works On My Machine™&quot;-style problems ever again!<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><p>Lots of teams are using it to:</p><ul><li>Set up consistent developer environments,</li><li>Reduce friction for new contributors,</li><li>Manage CI systems easily,</li><li>Reduce the amount of compute with artifact caching,</li><li>Build deployable packages easily.</li></ul><h3 id="the-workshop" tabindex="-1">The workshop <a class="header-anchor" href="#the-workshop" aria-label="Permalink to &quot;The workshop&quot;">​</a></h3><p>Join us for a full day of hands-on hacking on Nix; covering:</p><ul><li>Getting started,</li><li>Installing packages,</li><li>Development environments,</li><li>Deployment,</li><li>Testing,</li><li>and more!</li></ul><h3 id="essentials-where-when-how-much" tabindex="-1">Essentials: Where/When/How much <a class="header-anchor" href="#essentials-where-when-how-much" aria-label="Permalink to &quot;Essentials: Where/When/How much&quot;">​</a></h3><ul><li><em>When</em>: 29th of September</li><li><em>Cost</em>: £320.00 + VAT</li><li><em>Tickets</em>: <a href="https://luma.com/k65ttfw3" target="_blank" rel="noreferrer">Nix Workshop - Edinburgh - September 2026</a></li><li><em>Where</em>: <a href="https://maps.app.goo.gl/zb6wzxkEbsALbaEA8" target="_blank" rel="noreferrer">CodeBase</a>, Edinburgh.</li></ul><h3 id="why-a-nix-workshop" tabindex="-1">Why a Nix workshop? <a class="header-anchor" href="#why-a-nix-workshop" aria-label="Permalink to &quot;Why a Nix workshop?&quot;">​</a></h3><ul><li>Nix is amazing!</li><li>Getting started alone is very challenging,</li><li>Learn in a friendly small-group environment,</li><li>Hands on experience,</li><li>BYO ecosystems, get specific advice.</li></ul><h3 id="who-should-attend" tabindex="-1">Who should attend? <a class="header-anchor" href="#who-should-attend" aria-label="Permalink to &quot;Who should attend?&quot;">​</a></h3><p>People who are:</p><ul><li><p><em>Willing to hack</em>: This is a hands-on workshop; you will be expected to have your laptop, to be able to install things, and to be programming activities as we go.</p></li><li><p><em>Excited to learn</em>: Our goal will be to gain a deep and functional understanding of Nix and how to use it. Our aim isn&#39;t ticking off exercises, but being able to work with confidence in a sophisticated, powerful, but complex ecosystem.</p></li></ul><h4 id="which-programming-languages-will-you-support" tabindex="-1">Which programming languages will you support? <a class="header-anchor" href="#which-programming-languages-will-you-support" aria-label="Permalink to &quot;Which programming languages will you support?&quot;">​</a></h4><p>Our working examples will be in <code>Python</code>, <code>JavaScript</code>, and <code>Rust</code>, but there will be time to explore other ecosystems through-out the day. The general principles we will learn will be relevant to all languages and ecosystems, so you should find it valuable even if your day-to-day work is in a different space.</p><h4 id="will-i-need-access-to-an-ai-agent" tabindex="-1">Will I need access to an AI agent? <a class="header-anchor" href="#will-i-need-access-to-an-ai-agent" aria-label="Permalink to &quot;Will I need access to an AI agent?&quot;">​</a></h4><p>No; you can definitely use one if you wish, but the aim will be to be learning details that will help you either do further work yourself, or <em>guide</em> agents towards the right implementation approach.</p><h3 id="agenda" tabindex="-1">Agenda <a class="header-anchor" href="#agenda" aria-label="Permalink to &quot;Agenda&quot;">​</a></h3><p>We&#39;ll cover the following areas:</p><ul><li>Nix - What&#39;s it useful for?</li><li>Reproducible development environments</li><li>Packaging for deployment</li><li>Structuring your Nix codebase</li><li>Nixing and AI</li><li>What to do when things go wrong and how to fix them</li><li>Next steps</li></ul><p>This will be a hands-on workshop; a laptop is required; you will leave with real-world experience using Nix in your projects, for wildly increased joy of development!</p>',24),d=i('<hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>For the most part; <a href="https://fzakaria.com/2026/07/30/the-nix-sandbox-is-a-hidden-input" target="_blank" rel="noreferrer">of course there are caveats</a>, but Nix is the best-in-class here. <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',2);function p(u,m,g,f,w,b){const o=e("ArticleHeader"),t=e("ReachOut");return r(),l("div",null,[a(o,{title:"Nix Workshop in Edinburgh!",author:"Noon van der Silk",image:"noon"}),c,a(t),d])}const _=n(h,[["render",p]]);export{k as __pageData,_ as default};
